<template>
  <section class="riichi-admin">
    <p class="eyebrow">Event management</p><h1>Riichi Open I</h1>
    <p class="admin-lede">Manage the roster, payment checks and round records. Public scores change only when you certify a complete round.</p>
    <p v-if="error" class="admin-error" role="alert">{{ error }}</p><p v-if="message" class="admin-status" role="status">{{ message }}</p>
    <div v-if="loading" class="admin-card">Loading tournament records…</div>
    <template v-else-if="data">
      <section class="overview-grid">
        <article class="admin-card"><span>Event stage</span><strong>{{ humanize(data.event.stage) }}</strong></article>
        <article class="admin-card"><span>Places in use</span><strong>{{ usedPlaces }} / {{ data.event.capacity }}</strong></article>
        <article class="admin-card"><span>Awaiting payment check</span><strong>{{ pendingCount }}</strong></article>
        <article class="admin-card"><span>Registration</span><strong>{{ data.event.registration_open?'Open':'Closed' }}</strong></article>
      </section>

      <section id="overview" class="admin-section"><div class="section-title"><div><p class="eyebrow">Overview</p><h2>Event controls</h2></div><button class="admin-action" @click="toggleRegistration">{{ data.event.registration_open?'Close registration':'Open registration' }}</button></div><p class="admin-lede">Saturday, 14 November 2026 · 2:30 pm · Boardroom Bandit, Ara Damansara · RM10 · Winner’s prize</p></section>

      <section id="registrations" class="admin-section"><p class="eyebrow">Payment checks</p><h2>Registrations</h2><div v-if="!data.registrations.length" class="admin-card">No registrations yet.</div><div v-else class="registration-admin-list"><article v-for="registration in data.registrations" :key="registration.id" class="admin-card registration-card"><div class="registration-top"><div><h3>{{ registration.display_name }}</h3><span :class="['admin-badge',`status-${registration.status}`]">{{ humanize(registration.status) }}</span><small>Submitted {{ formatDate(registration.submitted_at) }} · Ref {{ registration.id.slice(0,8).toUpperCase() }}</small></div><button v-if="registration.receipt_path" class="admin-action secondary" @click="previewReceipt(registration)">View receipt</button><span v-else class="missing-receipt">No receipt</span></div><textarea v-model="registrationNotes[registration.id]" rows="2" placeholder="Private organiser note"></textarea><div class="action-row"><button class="admin-action" @click="setRegistration(registration,'verified')">Verify payment</button><button class="admin-action secondary" @click="setRegistration(registration,'needs_clarification')">Ask for clarification</button><button class="admin-action danger" @click="setRegistration(registration,'rejected')">Reject</button><button class="admin-action secondary" @click="setRegistration(registration,'cancelled')">Cancel</button></div></article></div></section>

      <section id="participants" class="admin-section"><div class="section-title"><div><p class="eyebrow">Roster</p><h2>Participants and check-in</h2></div></div><form class="admin-card admin-form-row add-player" @submit.prevent="addParticipant"><label>Name<input v-model="newParticipant.name" maxlength="80" required></label><label class="inline-check"><input v-model="newParticipant.verified" type="checkbox"> Payment checked</label><label v-if="newParticipant.verified">Verification reason<input v-model="newParticipant.reason" required placeholder="e.g. cash checked in person"></label><button class="admin-action">Add participant</button></form><div class="admin-table-wrap admin-card"><table class="admin-table"><thead><tr><th>Participant</th><th>Payment</th><th>Checked in</th><th>Substitute</th><th>Final eligible</th><th>Save</th></tr></thead><tbody><tr v-for="person in data.participants" :key="person.id"><td><input v-model="participantEdits[person.id].display_name" maxlength="80" aria-label="Participant name"></td><td>{{ paymentStatus(person) }}</td><td><input v-model="participantEdits[person.id].checked_in" type="checkbox" aria-label="Checked in"></td><td><input v-model="participantEdits[person.id].is_substitute" type="checkbox" aria-label="Substitute"></td><td><input v-model="participantEdits[person.id].eligible_for_final" type="checkbox" :disabled="participantEdits[person.id].is_substitute" aria-label="Eligible for final"></td><td><button class="admin-action secondary" @click="saveParticipant(person)">Save</button></td></tr></tbody></table></div><button class="admin-action" @click="drawFirstRound">Draw Qualifier 1 tables and seats</button></section>

      <section id="tables" class="admin-section"><p class="eyebrow">Assignments</p><h2>Tables and seating</h2><p class="admin-lede">Published assignments appear on public standings. Draft scores remain private.</p><div v-if="!data.rounds.length" class="admin-card">Draw the first round after the verified roster is checked in.</div><article v-for="round in data.rounds" :key="round.id" class="round-card admin-card"><div class="section-title"><h3>{{ humanize(round.round_key) }}</h3><span class="admin-badge">{{ humanize(round.status) }} · revision {{ round.draft_revision }}</span></div><div class="round-tables"><section v-for="table in tablesFor(round)" :key="table.id" class="table-editor"><h4>Table {{ table.table_number }} <small>{{ table.unclaimed_sticks }} unclaimed sticks</small></h4><div v-for="seat in seatsFor(table)" :key="seat.participant_id" class="seat-row"><span>{{ seat.seat_wind }}</span><strong>{{ participantName(seat.participant_id) }}</strong><input v-if="round.status!=='certified'" v-model.number="scores[table.id][seat.participant_id]" type="number" step="100" placeholder="Raw points" :aria-label="`${participantName(seat.participant_id)} raw points`"><span v-else>{{ pointsFor(table,seat.participant_id) }}</span></div><label v-if="round.status!=='certified'" class="sticks-label">Unclaimed sticks <input v-model.number="sticks[table.id]" type="number" min="0" max="100" step="1"></label><p v-if="scorePreviews[table.id]" class="preview-line">Preview · {{ scorePreviews[table.id] }}</p><button v-if="round.status!=='certified'" class="admin-action secondary" @click="saveTable(round,table)">Save table results</button></section></div></article></section>

      <section id="results" class="admin-section"><p class="eyebrow">Scoring record</p><h2>Enter results</h2><p class="admin-lede">Enter final raw points for all four players at each table. Uma is shared for tied places; points plus unclaimed sticks must total 120,000.</p><form class="admin-card admin-form-row" @submit.prevent="recordPenalty"><label>Round<select v-model="penalty.round_id"><option v-for="round in data.rounds.filter(r=>r.status!=='certified')" :key="round.id" :value="round.id">{{ humanize(round.round_key) }}</option></select></label><label>Participant<select v-model="penalty.participant_id"><option v-for="person in data.participants" :key="person.id" :value="person.id">{{ person.display_name }}</option></select></label><label>Penalty points<input v-model.number="penalty.points" type="number" min="0" step="0.1" required></label><label>Reason<input v-model="penalty.reason" required maxlength="500"></label><button class="admin-action">Record penalty</button></form><p class="admin-lede">Chombo is entered as 30.0 tournament points. Penalties stay separate from mahjong points.</p></section>

      <section id="certification" class="admin-section"><p class="eyebrow">Finish a complete round</p><h2>Round certification</h2><p class="admin-lede">Certification checks all expected tables in one transaction, locks the round and publishes its results.</p><article v-for="round in data.rounds" :key="`cert-${round.id}`" class="admin-card certify-row"><div><strong>{{ humanize(round.round_key) }}</strong><span>{{ resultCount(round) }} of {{ round.expected_tables*4 }} player scores saved</span></div><button v-if="round.status!=='certified'" class="admin-action" :disabled="busy" @click="certify(round)">Certify whole round</button><span v-else class="verified-badge">Certified {{ formatDate(round.certified_at) }}</span></article><button v-if="data.event.stage==='qualifier_1'&&data.rounds.some(r=>r.round_key==='qualifier_1'&&r.status==='certified')" class="admin-action" @click="prepareNext('qualifier_2')">Prepare Qualifier 2 snake tables</button><button v-if="data.event.stage==='qualifier_2'&&data.rounds.some(r=>r.round_key==='qualifier_2'&&r.status==='certified')" class="admin-action" @click="prepareNext('final')">Prepare Top 4 final table</button><form class="admin-card tie-draw-form" @submit.prevent="recordTieDraw"><h3>Record a public qualifying tie draw</h3><p>List tied player names in the order produced by the draw, one per line. The database checks that their qualifying tie-break values match.</p><label>Certified round<select v-model="tieDraw.round_id" required><option value="">Choose a round</option><option v-for="round in data.rounds.filter(r=>r.status==='certified'&&r.round_key.startsWith('qualifier'))" :key="round.id" :value="round.id">{{ humanize(round.round_key) }}</option></select></label><label>Draw order<textarea v-model="tieDraw.order" rows="3" placeholder="One player name per line" required></textarea></label><label>Public draw note<textarea v-model="tieDraw.note" rows="2" placeholder="e.g. Players drew numbered tiles in view of the table" required></textarea></label><button class="admin-action secondary">Save draw order</button></form></section>

      <section id="history" class="admin-section"><p class="eyebrow">Audit trail</p><h2>History and exports</h2><button class="admin-action secondary" @click="exportData">Download organiser export</button><ul class="audit-list"><li v-for="entry in data.audit" :key="entry.id"><strong>{{ humanize(entry.action) }}</strong><span>{{ entry.entity_type }} · {{ formatDate(entry.created_at) }}</span><small>{{ entry.reason || entry.entity_id }}</small></li></ul></section>
    </template>
    <div v-if="preview" class="receipt-overlay" @click.self="preview=null"><section class="receipt-dialog"><button class="close-preview" aria-label="Close receipt preview" @click="preview=null">×</button><img v-if="preview.mime.startsWith('image/')" :src="preview.url" alt="Private payment receipt"><iframe v-else :src="preview.url" title="Private payment receipt PDF"></iframe><a :href="preview.url" target="_blank" rel="noreferrer">Open receipt in a new tab</a></section></div>
  </section>
</template>

<script setup>
import { scoreFourPlayerTable } from '~/utils/riichiOpenScoring.js'
definePageMeta({layout:'admin'})
useHead({title:'Riichi Open admin | Saujana BGC',meta:[{name:'robots',content:'noindex, nofollow, noarchive'}]})
const {callAdmin}=useRiichiOpen(),auth=useAdminAuth(),route=useRoute()
const data=ref(null),loading=ref(true),busy=ref(false),error=ref(''),message=ref(''),preview=ref(null)
const registrationNotes=reactive({}),participantEdits=reactive({}),scores=reactive({}),sticks=reactive({}),scorePreviews=reactive({})
const newParticipant=reactive({name:'',verified:false,reason:''}),penalty=reactive({round_id:'',participant_id:'',points:0,reason:''})
const tieDraw=reactive({round_id:'',order:'',note:''})
const usedPlaces=computed(()=>Math.min(data.value?.event.capacity??16,(data.value?.registrations??[]).filter(r=>['pending','verified','needs_clarification'].includes(r.status)).length+(data.value?.active_holds??0)))
const pendingCount=computed(()=>data.value?.registrations.filter(r=>['pending','needs_clarification','payment_exception'].includes(r.status)).length??0)

onMounted(async()=>{await load();await nextTick();scrollToHash()})
watch(()=>route.hash,async()=>{await nextTick();scrollToHash()})
async function load(){loading.value=true;error.value='';try{data.value=await callAdmin('overview');for(const row of data.value.registrations)registrationNotes[row.id]=row.private_note??'';for(const row of data.value.participants)participantEdits[row.id]={display_name:row.display_name,checked_in:row.checked_in,is_substitute:row.is_substitute,eligible_for_final:row.eligible_for_final};for(const table of data.value.tables){scores[table.id]??={};sticks[table.id]=table.unclaimed_sticks;for(const result of data.value.results.filter(r=>r.table_id===table.id))scores[table.id][result.participant_id]=result.raw_points}if(!penalty.round_id)penalty.round_id=data.value.rounds.find(r=>r.status!=='certified')?.id??''}catch(cause){error.value=cause.message}finally{loading.value=false}}
async function act(action,payload={}){busy.value=true;error.value='';message.value='';try{const result=await callAdmin(action,payload);await load();return result}catch(cause){error.value=cause.message;return null}finally{busy.value=false}}
async function toggleRegistration(){const result=await act('registration_open',{open:!data.value.event.registration_open});if(result)message.value=`Registration ${data.value.event.registration_open?'closed':'opened'}.`}
async function previewReceipt(registration){try{const result=await callAdmin('receipt_url',{path:registration.receipt_path});preview.value={url:result.url,mime:registration.receipt_mime}}catch(cause){error.value=cause.message}}
async function setRegistration(registration,status){if(status==='verified'&&!registration.receipt_path&&registrationNotes[registration.id]?.trim().length<4){error.value='Add a private reason before verifying a registration without a receipt.';return}const result=await act('registration_status',{registration_id:registration.id,status,private_note:registrationNotes[registration.id],manual_verification:status==='verified'&&!registration.receipt_path});if(result)message.value=`${registration.display_name}: ${humanize(status)}.`}
async function addParticipant(){const result=await act('add_participant',{name:newParticipant.name,payment_verified:newParticipant.verified,reason:newParticipant.reason});if(result){message.value='Participant added.';newParticipant.name='';newParticipant.reason='';newParticipant.verified=false}}
async function saveParticipant(person){const result=await act('participant_update',{participant_id:person.id,...participantEdits[person.id],reason:'Roster update'});if(result)message.value='Participant details saved.'}
async function drawFirstRound(){const result=await act('generate_q1');if(result)message.value=`${result.players} players seated across ${result.tables} tables.`}
function tablesFor(round){return data.value.tables.filter(table=>table.round_id===round.id)}
function seatsFor(table){return data.value.seats.filter(seat=>seat.table_id===table.id).sort((a,b)=>['East','South','West','North'].indexOf(a.seat_wind)-['East','South','West','North'].indexOf(b.seat_wind))}
function participantName(id){return data.value.participants.find(person=>person.id===id)?.display_name??'Unknown participant'}
function pointsFor(table,id){return data.value.results.find(r=>r.table_id===table.id&&r.participant_id===id)?.raw_points??'—'}
function resultCount(round){return data.value.results.filter(result=>result.round_id===round.id).length}
async function saveTable(round,table){try{const results=seatsFor(table).map(seat=>({participant_id:seat.participant_id,raw_points:Number(scores[table.id]?.[seat.participant_id])}));const scored=scoreFourPlayerTable(results.map(row=>({id:row.participant_id,rawPoints:row.raw_points})),Number(sticks[table.id]??0));scorePreviews[table.id]=scored.map(row=>`${participantName(row.id)} ${row.score>=0?'+':''}${row.score.toFixed(1)}`).join(' · ');const result=await act('save_table',{round_id:round.id,table_id:table.id,revision:round.draft_revision,unclaimed_sticks:Number(sticks[table.id]??0),results});if(result)message.value=`Table ${table.table_number} saved as draft.`}catch(cause){error.value=cause.message}}
async function recordPenalty(){const round=data.value.rounds.find(r=>r.id===penalty.round_id);const result=await act('penalty',{...penalty,revision:round?.draft_revision??0});if(result){message.value='Penalty recorded.';penalty.reason='';penalty.points=0}}
async function certify(round){const result=await act('certify_round',{round_id:round.id,revision:round.draft_revision});if(result)message.value=`Round certified. Event moved to ${humanize(result.next_stage)}.`}
async function prepareNext(roundKey){const result=await act('prepare_round',{round_key:roundKey});if(result)message.value=`${humanize(roundKey)} seating is ready.`}
async function recordTieDraw(){const round=data.value.rounds.find(row=>row.id===tieDraw.round_id);const names=tieDraw.order.split(/[\n,→]+/).map(name=>name.trim()).filter(Boolean);if(!round||names.length<2){error.value='Enter at least two tied players in draw order.';return}const ids=[];for(const name of names){const person=data.value.participants.find(row=>row.id.toLowerCase()===name.toLowerCase()||row.display_name.trim().toLowerCase()===name.toLowerCase());if(!person){error.value=`Could not match “${name}”. Use the exact public name; duplicate names need a participant ID.`;return}if(ids.includes(person.id)){error.value='A player can appear only once in the draw order.';return}ids.push(person.id)}const result=await act('record_tie_draw',{round_id:round.id,participant_ids:ids,order_ids:ids,public_note:tieDraw.note});if(result){tieDraw.order='';tieDraw.note='';message.value='Public draw order recorded.'}}
async function exportData(){try{const output=await callAdmin('export');const blob=new Blob([JSON.stringify(output,null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='riichi-open-i-organiser-export.json';link.click();URL.revokeObjectURL(link.href)}catch(cause){error.value=cause.message}}
function paymentStatus(person){return data.value.registrations.find(row=>row.id===person.registration_id)?.status??'No linked registration'}
function formatDate(value){return value?new Date(value).toLocaleString('en-MY',{dateStyle:'medium',timeStyle:'short'}):'—'}
function humanize(value=''){return String(value).replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase())}
function scrollToHash(){const id=route.hash.slice(1);if(id)document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'})}
</script>

<style scoped>
.tie-draw-form{display:grid;gap:12px;margin-top:15px}.tie-draw-form h3{font:1.2rem var(--font-display);color:var(--matcha-leaf);margin:0}.tie-draw-form p{margin:0;color:var(--muted);font-size:.83rem;line-height:1.55}.tie-draw-form label{display:grid;gap:6px;font-size:.82rem}.tie-draw-form select,.tie-draw-form textarea{font:inherit;padding:9px;border:1px solid var(--line);border-radius:5px}
</style>
